import type { System } from '../../Engine/System';
import type { World } from '../../Engine/World';
import { GridMap } from '../Data/GridMap';
import { HallEvents } from '../HallEvents';
import type { BuildingEntity } from '../Entity/BuildingEntity';

export class GridSyncSystem implements System {
    private _world: World = null!;
    private _gridMap: GridMap;

    constructor(gridMap: GridMap) {
        this._gridMap = gridMap;
    }

    onStart(world: World): void {
        this._world = world;
        world.bus.on(HallEvents.BUILD_COMPLETED, this._onBuildCompleted, this);
        // 预留：未来拆除建筑时
        // world.bus.on(HallEvents.BUILD_REMOVED, this._onBuildRemoved, this);
    }

    onDestroy(world: World): void {
        world.bus.off(HallEvents.BUILD_COMPLETED, this._onBuildCompleted, this);
        // world.bus.off(HallEvents.BUILD_REMOVED, this._onBuildRemoved, this);
        this._world = null!;
    }

    onTick(): void {}

    private _onBuildCompleted(b: BuildingEntity): void {
        // 唯一的记账入口
        this._gridMap.place(b.gridX, b.gridY, b);
    }
    
    // 预留：未来拆除时清理格子
    // private _onBuildRemoved(b: BuildingEntity): void {
    //     this._gridMap.remove(b.gridX, b.gridY);
    // }
}